bool runS4CertificationForProject(const QString& root){ProjectModel model;ProjectPersistence p;QString error;const QString file=QDir(root).filePath("ARAMF_WORKER.aramf.json");if(!p.load(&model,file,&error))return false;int iteration=1;if(model.compositionEncapsulation().lifecycleHistory.isEmpty()){S4::Configuration c;const QString host=model.responsibilityOwnership().rootId;const QString child=host;c.metadata.insert("legacyBaseline",true);model.setCompositionEncapsulation(c);if(!model.startS4Iteration(&error))return false;}else{iteration=model.compositionEncapsulation().lifecycleHistory.last().iteration+1;if(!model.reworkS4(&error))return false;}if(model.compositionEncapsulation().lifecycle.iteration!=iteration||model.compositionEncapsulation().lifecycle.certification!=0||model.compositionEncapsulation().lifecycle.done!=0)return false;if(!p.save(model,file,&error))return false;QByteArray material;const QStringList files={"CMakeLists.txt","src/core/ProcessVersion.h","src/core/ProcessVersion.cpp","src/core/ProjectModel.h","src/core/ProjectModel.cpp","src/core/ProjectPersistence.cpp","src/core/Services.cpp","src/structure/S1/ResponsibilityOwnership.h","src/structure/S2/PhysicalStructure.h","src/structure/S3/DependencyInterfaces.h","src/structure/S4/CompositionEncapsulation.h","src/structure/S4/CompositionEncapsulation.cpp","src/structure/S4/S4CertificationService.h","src/structure/S4/S4CertificationService.cpp","tests/ProjectMemoryTests.cpp","tests/S4CompositionEncapsulationTests.cpp","tests/S4CertificationTests.cpp"};for(const auto&x:files){QFile f(QDir::current().filePath(x));if(!f.open(QIODevice::ReadOnly))return false;material.append(x.toUtf8());material.append('\0');material.append(f.readAll());material.append('\0');}const QString fp=QString::fromLatin1(QCryptographicHash::hash(material,QCryptographicHash::Sha256).toHex());QProcess git;git.start("git",{"rev-parse","HEAD"});if(!git.waitForFinished(10000)||git.exitCode()!=0)return false;const QString commit=QString::fromUtf8(git.readAllStandardOutput()).trimmed();QJsonObject issued;if(!S4::CertificationServiceAdapter::certify(root,model.compositionEncapsulation(),model.responsibilityOwnership(),model.physicalStructure(),model.dependencyInterfaces(),QStringLiteral("%1:S4:%2").arg(commit,fp),{{"suite","aramf_s4_tests"},{"status","PASS"},{"passed",1},{"failed",0},{"regression","CTest 9/9 PASS"}},iteration,&issued,&error))return false;if(issued.value("subject").toString()!="S4")return false;if(!model.certifyS4Iteration(&error)||!model.completeS4Iteration(&error))return false;if(!p.save(model,file,&error))return false;return GenerationServices().generate(model,model.generationOptions()).success;}
